16	// 保存的档案集合中，用于查找每份档案的编号（对象键）与该份登记内容里的 id
17	// 必须都是非空白文本，且是同一个编号。两处编号不同，或登记内容的 id 缺失、
18	// 为 null、为空串、只有空白时，即使 JSON 能解析、其余期限/冻结信息都合法，
19	// Open 也必须按保存记录损坏失败（ErrCorruptState），错误能区分“编号不一致”
20	// 与“缺少有效编号”，且原文件保持原样。
21	func TestOpenRejectsArchiveIdentityMismatch(t *testing.T) {
22		// active 与 released 两条冻结记录都合法，供对照“合法冻结不能掩盖编号矛盾”。
23		activeFreeze := `{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":false}`
24		releasedFreeze := `{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-06"}`
25		// rec 构造一份登记记录；idText 给出记录内容里 id 字段的原始 JSON 文本，
26		// 允许写出 null、空串、Unicode 转义等特殊形式。
27		rec := func(idText, category, end, freezes string) string {
28			return `{"id":` + idText + `,"category":"` + category + `","start":"2020-01-01","end":"` + end +
29				`","initial_end":"` + end + `","destroyed":false,"freezes":[` + freezes + `]}`
30		}
31		entry := func(key, recordJSON string) string { return `"` + key + `":` + recordJSON }
32		state := func(entries string) string {
33			return `{"version":1,"archives":{` + entries + `},"manifests":{}}`
34		}
35	
36		corrupt := map[string]struct {
37			state    string
38			wantAll  []string
39			wantKind string
40		}{
41			"挂在A-1名下id写成A-2": {
42				state(entry("A-1", rec(`"A-2"`, "合同", "2025-01-10", ""))),
43				[]string{"A-1", "A-2"}, "不一致",
44			},
45			"id字段缺失": {
46				// 去掉 id 字段：记录直接以 category 开头。
47				`{"version":1,"archives":{"A-1":` +
48					`{"category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","destroyed":false,"freezes":[]}` +
49					`},"manifests":{}}`,
50				[]string{"A-1", "id"}, "缺少",
51			},
52			"id为null": {
53				state(entry("A-1", rec(`null`, "合同", "2025-01-10", ""))),
54				[]string{"A-1", "id"}, "缺少",
55			},
56			"id为空串": {
57				state(entry("A-1", rec(`""`, "合同", "2025-01-10", ""))),
58				[]string{"A-1", "id"}, "缺少",
59			},
60			"id只有空白": {
61				state(entry("A-1", rec(`"   "`, "合同", "2025-01-10", ""))),
62				[]string{"A-1", "id"}, "缺少",
63			},
64			"id只有制表符与换行": {
65				state(entry("A-1", rec(`"\t\n "`, "合同", "2025-01-10", ""))),
66				[]string{"A-1", "id"}, "缺少",
67			},
68			"仅大小写不同不算一致": {
69				state(entry("A-1", rec(`"a-1"`, "合同", "2025-01-10", ""))),
70				[]string{"A-1", "a-1"}, "不一致",
71			},
72			"仅首尾空白不同不算一致": {
73				state(entry("A-1", rec(`" A-1 "`, "合同", "2025-01-10", ""))),
74				[]string{"A-1", " A-1 "}, "不一致",
75			},
76			"id通过Unicode转义写成另一个编号": {
77				// 键直接写 A-1；id 的源文本是 A- 紧接 2 的 Unicode 转义，
78				// JSON 解码后为 A-2，按解码后文本比较即不一致。
79				state(entry("A-1", rec(`"`+esc2+`"`, "合同", "2025-01-10", ""))),
80				[]string{"A-1", "A-2"}, "不一致",
81			},
82			"带未解除冻结且期限合法仍因编号矛盾拒绝": {
83				state(entry("A-1", rec(`"A-2"`, "合同", "2025-01-10", activeFreeze))),
84				[]string{"A-1", "A-2"}, "不一致",
85			},
86			"用于查找的键为纯空白": {
87				state(entry(" ", rec(`"A-1"`, "合同", "2025-01-10", ""))),
88				[]string{"空白"}, "空白",
89			},
90			"用于查找的键为空串": {
91				`{"version":1,"archives":{"":` + rec(`"A-1"`, "合同", "2025-01-10", "") +
92					`},"manifests":{}}`,
93				[]string{"空白"}, "空白",
94			},
95			"多份档案中第二份身份矛盾": {
96				state(entry("A-1", rec(`"A-1"`, "合同", "2025-01-10", "")) + "," +
97					entry("B-7", rec(`"B-8"`, "凭证", "2025-06-30", ""))),
98				[]string{"B-7", "B-8"}, "不一致",
99			},
100		}
101		for name, tc := range corrupt {
102			t.Run(name, func(t *testing.T) {
103				dir := t.TempDir()
104				writeStateFile(t, dir, tc.state)
105	
106				s, err := Open(dir)
107				if err == nil {
108					s.Close()
109					t.Fatal("档案编号与查找编号不一致时不应打开成功")
110				}
111				if !errors.Is(err, ErrCorruptState) {
112					t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
113				}
114				msg := err.Error()
115				for _, want := range tc.wantAll {
116					if !strings.Contains(msg, want) {
117						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
118					}
119				}
120				if !strings.Contains(msg, tc.wantKind) {
121					t.Fatalf("错误信息应能识别为 %q 类问题，得到 %v", tc.wantKind, err)
122				}
123				if got := readStateFile(t, dir); got != tc.state {
124					t.Fatalf("打开失败后原文件被改动:\n%q", got)
125				}
126			})
127		}
128	
129		// 已销毁档案：清册归属、条目快照、处理日期、解除信息都合法，只有登记内容
130		// 的 id 与查找编号不一致——合法的清册归属不能掩盖编号矛盾。
131		t.Run("已销毁档案身份矛盾同样拒绝", func(t *testing.T) {
132			content := `{"version":1,"archives":{"A-1":` +
133				`{"id":"A-2","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","destroyed":true,"manifest_id":"APP-1","freezes":[` +
134				releasedFreeze + `]}},"manifests":{"APP-1":` +
135				`{"application_id":"APP-1","processed_on":"2025-01-10","entries":[` +
136				`{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10"}]}}}`
137			dir := t.TempDir()
138			writeStateFile(t, dir, content)
139			s, err := Open(dir)
140			if err == nil {
141				s.Close()
142				t.Fatal("已销毁档案的编号矛盾不能被合法清册掩盖")
143			}
144			if !errors.Is(err, ErrCorruptState) ||
145				!strings.Contains(err.Error(), "A-1") || !strings.Contains(err.Error(), "A-2") ||
146				!strings.Contains(err.Error(), "不一致") {
147				t.Fatalf("应报档案编号不一致并给出两处编号，得到 %v", err)
148			}
149			if got := readStateFile(t, dir); got != content {
150				t.Fatalf("打开失败后原文件被改动:\n%q", got)
151			}
152		})
153	
154		// 对照组：键与 id 解码后为同一文本即合法——包括两侧分别使用 Unicode 转义、
155		// 正常保存的带冻结档案、没有修订信息的旧档案。
156		t.Run("身份一致的记录对照组", func(t *testing.T) {
157			valid := map[string]string{
158				"键与id直接写出且相同": state(
159					entry("A-1", rec(`"A-1"`, "合同", "2025-01-10", activeFreeze))),
160				"键用Unicode转义id直接写出": state(
161					entry(esc1, rec(`"A-1"`, "合同", "2025-01-10", activeFreeze))),
162				"键直接写出id用Unicode转义": state(
163					entry("A-1", rec(`"`+esc1+`"`, "合同", "2025-01-10", ""))),
164				"两侧都用Unicode转义解码后相同": state(
165					entry(esc1, rec(`"`+esc1+`"`, "合同", "2025-01-10", ""))),
166				"不同编号各登记一次不受影响": state(
167					entry("A-1", rec(`"A-1"`, "合同", "2025-01-10", activeFreeze)) + "," +
168						entry("A-2", rec(`"A-2"`, "合同", "2025-01-10", activeFreeze))),
169				"旧档案缺少initial_end": `{"version":1,"archives":{"A-1":` +
170					`{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","destroyed":false,"freezes":[]}` +
171					`},"manifests":{}}`,
172			}
173			for name, content := range valid {
174				t.Run(name, func(t *testing.T) {
175					dir := t.TempDir()
176					writeStateFile(t, dir, content)
177					s, err := Open(dir)
178					if err != nil {
179						t.Fatalf("身份一致的记录应能打开: %v", err)
180					}
181					defer s.Close()
182				})
183			}
184		})
185	}
186	
187	// 保管库打开后保存内容才出现档案编号矛盾：下一次使用有效输入查询历史、
188	// 取回清册、销毁前核对或办理业务，即使操作的是另一份正常档案，也必须按
189	// 整库记录损坏失败——不返回正常历史、清册或部分报告，不改变档案状态或
190	// 生成清册，原保存内容保持原样；恢复一致后记录继续可用。
191	func TestArchiveIdentityMismatchAfterOpenFailsAllOperations(t *testing.T) {
192		dir := t.TempDir()
193		s, err := Open(dir)
194		if err != nil {
195			t.Fatal(err)
196		}
197		defer s.Close()
198		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
199		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
200		reg(t, s, "A-3", "单据", "2020-01-01", "2025-01-10")
201		if err := s.Freeze(FreezeInput{
202			ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05"),
203		}); err != nil {
204			t.Fatal(err)
205		}
206		if _, err := s.Destroy(DestructionRequest{
207			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
208		}); err != nil {
209			t.Fatal(err)
210		}
211		if _, found, err := s.GetManifest("APP-3"); err != nil || !found {
212			t.Fatalf("损坏前清册应可取回: found=%v err=%v", found, err)
213		}
214	
215		// 把 A-1 登记内容里的 id 改成 A-2：记录仍挂在 A-1 名下，却自称 A-2。
216		good := readStateFile(t, dir)
217		rewriteState(t, dir, func(doc map[string]any) {
218			doc["archives"].(map[string]any)["A-1"].(map[string]any)["id"] = "A-2"
219		})
220		corruptContent := readStateFile(t, dir)
221	
222		// 重新打开必须失败，错误说明档案编号不一致并给出两处编号。
223		s2, err := Open(dir)
224		if err == nil {
225			s2.Close()
226			t.Fatal("档案编号与查找编号不一致时，打开必须失败")
227		}
228		if !errors.Is(err, ErrCorruptState) ||
229			!strings.Contains(err.Error(), "A-1") || !strings.Contains(err.Error(), "A-2") ||
230			!strings.Contains(err.Error(), "不一致") {
231			t.Fatalf("打开错误应为 ErrCorruptState 并指出两处编号不一致，得到 %v", err)
232		}
233	
234		// 已打开实例：即使本次只操作与矛盾记录无关的正常档案 A-2，也必须整库失败。
235		if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
236			t.Fatalf("损坏后查询无关档案也必须失败且无结论: found=%v err=%v", found, err)
237		}
238		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
239			t.Fatalf("损坏后查询矛盾档案不得返回标着 A-2 的历史: found=%v err=%v", found, err)
240		}
241		if m, found, err := s.GetManifest("APP-3"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
242			t.Fatalf("损坏后取回清册必须失败: found=%v err=%v %+v", found, err, m)
243		}
244		if r, err := s.Check(CheckRequest{
245			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
246		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
247			t.Fatalf("损坏后核对必须失败且不得给出部分报告: %+v err=%v", r, err)
248		}
249		if m, err := s.Destroy(DestructionRequest{
250			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
251		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
252			t.Fatalf("损坏后销毁必须失败且不得把错误编号写进清册: %+v err=%v", m, err)
253		}
254		if err := s.Register(RegisterInput{
255			ID: "A-4", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-06-30"),
256		}); !errors.Is(err, ErrCorruptState) {
257			t.Fatalf("损坏后 Register 必须失败: %v", err)
258		}
259		if err := s.Freeze(FreezeInput{
260			ArchiveID: "A-2", FreezeID: "F-X", Reason: "诉讼", FrozenOn: MustParseDate("2025-06-01"),
261		}); !errors.Is(err, ErrCorruptState) {
262			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
263		}
264		if err := s.Release(ReleaseInput{
265			ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-08"),
266		}); !errors.Is(err, ErrCorruptState) {
267			t.Fatalf("损坏后 Release 必须失败: %v", err)
268		}
269		if _, err := s.Revise(ReviseInput{
270			RevisionID: "R-9", ArchiveID: "A-2",
271			OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
272			RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
273		}); !errors.Is(err, ErrCorruptState) {
274			t.Fatalf("损坏后 Revise 必须失败: %v", err)
275		}
276	
277		// 失败不得触发修复：不改号、不补写，原保存内容保持原样。
278		if got := readStateFile(t, dir); got != corruptContent {
279			t.Fatalf("失败后原保存内容被改动:\n%q", got)
280		}
281	
282		// 恢复一致后整库恢复可用：A-1 的身份与冻结历史仍是损坏前的样子。
283		writeStateFile(t, dir, good)
284		h, found, err := s.History("A-1")
285		if err != nil || !found {
286			t.Fatalf("恢复后查询应成功: found=%v err=%v", found, err)
287		}
288		if h.ID != "A-1" || len(h.Freezes) != 1 || h.Freezes[0].ID != "F-1" || h.Freezes[0].Released {
289			t.Fatalf("恢复后 A-1 身份与冻结历史应保持原样: %+v", h)
290		}
291		if _, found, err := s.GetManifest("APP-3"); err != nil || !found {
292			t.Fatalf("恢复后已销毁档案的清册应保持可查: found=%v err=%v", found, err)
293		}
294	}
295	
296	// 保管库打开后登记内容的 id 才缺失：与编号不一致一样按整库记录损坏失败，
297	// 下一次有效输入的任何操作都不返回正常结果，即使操作的是另一份正常档案。
298	func TestArchiveIdentityMissingIDAfterOpenFailsWholeVault(t *testing.T) {
299		dir := t.TempDir()
300		s, err := Open(dir)
301		if err != nil {
302			t.Fatal(err)
303		}
304		defer s.Close()
305		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
306		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
307	
308		rewriteState(t, dir, func(doc map[string]any) {
309			delete(doc["archives"].(map[string]any)["A-1"].(map[string]any), "id")
310		})
311		corruptContent := readStateFile(t, dir)
312	
313		s2, err := Open(dir)
314		if err == nil {
315			s2.Close()
316			t.Fatal("登记内容缺少 id 时打开必须失败")
317		}
318		if !errors.Is(err, ErrCorruptState) ||
319			!strings.Contains(err.Error(), "A-1") || !strings.Contains(err.Error(), "缺少") {
320			t.Fatalf("应报缺少有效编号并指出查找编号 A-1，得到 %v", err)
321		}
322		if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
323			t.Fatalf("id 缺失后查询另一份正常档案也必须失败: found=%v err=%v", found, err)
324		}
325		if r, err := s.Check(CheckRequest{
326			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
327		}); !errors.Is(err, ErrCorruptState) || r.Status != "" {
328			t.Fatalf("id 缺失后核对必须整次失败: %+v err=%v", r, err)
329		}
330		if got := readStateFile(t, dir); got != corruptContent {
331			t.Fatalf("失败后原保存内容被改动:\n%q", got)
332		}
333	}
