1	package retention
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7	)
8	
9	// RegisterInput 是登记一份档案所需的信息。
10	//
11	// 编号和类别不能是空白；日期必须是 ParseDate 能解析的真实日期；
12	// 截止日可以与起算日相同，但不能更早。
13	type RegisterInput struct {
14		ID       string
15		Category string
16		Start    Date
17		End      Date
18	}
19	
20	// FreezeInput 是为档案新增一条冻结所需的信息。
21	type FreezeInput struct {
22		ArchiveID string
23		FreezeID  string
24		Reason    string
25		FrozenOn  Date
26	}
27	
28	// ReleaseInput 是解除一条冻结所需的信息。
29	type ReleaseInput struct {
30		ArchiveID  string
31		FreezeID   string
32		Reason     string
33		ReleasedOn Date
34	}
35	
36	// ReviseInput 是一次保管截止日修订所需的信息。
37	//
38	// 修订编号在整个保管库内唯一，且与销毁申请编号互不占用；
39	// OriginalEnd 是调用者看到的当前截止日，用于发现他人已改动期限；
40	// NewEnd 不能早于起算日，也不能等于所提交的原截止日；
41	// RevisedOn 仅用于记录，提交成功即采用新期限。
42	// 编号与原因去除首尾空白后不得为空白，文本比较以去空白后的值为准。
43	type ReviseInput struct {
44		RevisionID  string
45		ArchiveID   string
46		OriginalEnd Date
47		NewEnd      Date
48		RevisedOn   Date
49		Reason      string
50	}
51	
52	// DestructionRequest 是一次销毁申请。
53	//
54	// 一次申请可以选择多个档案。申请编号在所有成功申请中唯一，
55	// 处理日期即判断档案是否到期所依据的日期。
56	type DestructionRequest struct {
57		ApplicationID string
58		ProcessedOn   Date
59		ArchiveIDs    []string
60	}
61	
62	// CheckRequest 是销毁前一次只做核对的请求，字段含义与 DestructionRequest 相同。
63	//
64	// 核对不销毁任何档案、不生成或改写清册，也不占用申请编号：
65	// 核对失败或发现阻碍后，仍可沿用同一编号继续核对或正式提交。
66	type CheckRequest struct {
67		ApplicationID string
68		ProcessedOn   Date
69		ArchiveIDs    []string
70	}
71	
72	// normalizeText 去除首尾空白；空白字段统一按空白处理，避免同值异写。
73	func normalizeText(s string) string { return strings.TrimSpace(s) }
74	
75	func requireText(value, name string) (string, error) {
76		v := normalizeText(value)
77		if v == "" {
78			return "", fmt.Errorf("retention: %s不能为空白: %w", name, ErrBlankField)
79		}
80		return v, nil
81	}
82	
83	func requireDate(d Date, name string) error {
84		if d.IsZero() {
85			return fmt.Errorf("retention: %s缺失或无效，应为 YYYY-MM-DD: %w", name, ErrInvalidDate)
86		}
87		return nil
88	}
89	
90	// Register 登记一份档案。
91	//
92	// 编号重复或任一输入无效时明确失败，并且不写盘，已有记录不受影响。
93	func (s *Store) Register(in RegisterInput) error {
94		id, err := requireText(in.ID, "档案编号")
95		if err != nil {
96			return err
97		}
98		category, err := requireText(in.Category, "类别")
99		if err != nil {
100			return err
101		}
102		if err := requireDate(in.Start, "起算日"); err != nil {
103			return err
104		}
105		if err := requireDate(in.End, "保管截止日"); err != nil {
106			return err
107		}
108		if in.End.Before(in.Start) {
109			return fmt.Errorf("retention: 档案 %s 的保管截止日 %s 早于起算日 %s: %w",
110				id, in.End, in.Start, ErrRetentionEndBeforeStart)
111		}
112		return s.mutate(func(data *storeData) error {
113			if _, exists := data.Archives[id]; exists {
114				return fmt.Errorf("retention: 档案编号 %s 已登记: %w", id, ErrDuplicateID)
115			}
116			data.Archives[id] = &archiveRecord{
117				ID:         id,
118				Category:   category,
119				Start:      in.Start,
120				End:        in.End,
121				InitialEnd: in.End,
122				Freezes:    nil,
123			}
124			return nil
125		})
126	}
127	
128	// Freeze 为档案登记一条冻结。
129	//
130	// 冻结编号在同一档案内唯一。档案不存在、已销毁、冻结编号重复或输入无效时失败。
131	func (s *Store) Freeze(in FreezeInput) error {
132		archiveID, err := requireText(in.ArchiveID, "档案编号")
133		if err != nil {
134			return err
135		}
136		freezeID, err := requireText(in.FreezeID, "冻结编号")
137		if err != nil {
138			return err
139		}
140		reason, err := requireText(in.Reason, "冻结原因")
141		if err != nil {
142			return err
143		}
144		if err := requireDate(in.FrozenOn, "冻结日期"); err != nil {
145			return err
146		}
147		return s.mutate(func(data *storeData) error {
148			ar, ok := data.Archives[archiveID]
149			if !ok {
150				return fmt.Errorf("retention: 档案 %s 不存在，不能新增冻结: %w", archiveID, ErrNotFound)
151			}
152			if ar.Destroyed {
153				return fmt.Errorf("retention: 档案 %s 已销毁，不能新增冻结: %w", archiveID, ErrDestroyed)
154			}
155			for _, f := range ar.Freezes {
156				if f.ID == freezeID {
157					return fmt.Errorf("retention: 档案 %s 内冻结编号 %s 已存在: %w",
158						archiveID, freezeID, ErrDuplicateFreezeID)
159				}
160			}
161			ar.Freezes = append(ar.Freezes, &freezeRecord{
162				ID:       freezeID,
163				Reason:   reason,
164				FrozenOn: &in.FrozenOn,
165			})
166			return nil
167		})
168	}
169	
170	// Release 解除一条冻结。
171	//
172	// 必须填写解除日期与原因，解除日期不能早于该冻结的冻结日期。
173	// 解除只在原记录上标记，不删除冻结记录，也不影响同一档案的其他冻结。
174	// 不能解除不存在或已经解除的冻结。
175	func (s *Store) Release(in ReleaseInput) error {
176		archiveID, err := requireText(in.ArchiveID, "档案编号")
177		if err != nil {
178			return err
179		}
180		freezeID, err := requireText(in.FreezeID, "冻结编号")
181		if err != nil {
182			return err
183		}
184		reason, err := requireText(in.Reason, "解除原因")
185		if err != nil {
186			return err
187		}
188		if err := requireDate(in.ReleasedOn, "解除日期"); err != nil {
189			return err
190		}
191		return s.mutate(func(data *storeData) error {
192			ar, ok := data.Archives[archiveID]
193			if !ok {
194				return fmt.Errorf("retention: 档案 %s 不存在: %w", archiveID, ErrNotFound)
195			}
196			var fr *freezeRecord
197			for _, f := range ar.Freezes {
198				if f.ID == freezeID {
199					fr = f
200					break
201				}
202			}
203			if fr == nil {
204				return fmt.Errorf("retention: 档案 %s 下冻结 %s 不存在: %w",
205					archiveID, freezeID, ErrFreezeNotFound)
206			}
207			if fr.Released {
208				return fmt.Errorf("retention: 档案 %s 的冻结 %s 已经解除，不能重复解除: %w",
209					archiveID, freezeID, ErrFreezeAlreadyReleased)
210			}
211			// 通过 load 校验的冻结必然带有有效冻结日期。
212			if in.ReleasedOn.Before(*fr.FrozenOn) {
213				return fmt.Errorf("retention: 解除日期 %s 早于冻结 %s 的冻结日期 %s: %w",
214					in.ReleasedOn, freezeID, *fr.FrozenOn, ErrReleaseBeforeFreeze)
215			}
216			fr.Released = true
217			fr.ReleaseReason = reason
218			releasedOn := in.ReleasedOn
219			fr.ReleasedOn = &releasedOn
220			return nil
221		})
222	}
223	
224	// Revise 修订一份尚未销毁档案的保管截止日，不必重新登记；
225	// 编号、类别、起算日不可改动。被冻结的档案也允许修订，但修订不解除冻结，
226	// 期限缩短后仍要满足原有冻结规则才能销毁。
227	//
228	// 首次办理时，所提交的原截止日必须与当前保存值相同，否则返回
229	// RetentionEndChangedError（errors.Is 可判定 ErrRetentionEndChanged），
230	// 其中带有当前截止日，不会覆盖他人的修改。成功后返回一条修订记录，
231	// 同时更新当前截止日；任何失败都不改变期限或留下修订历史。
232	//
233	// 修订编号在整个保管库内唯一，与销毁申请编号互不占用。同编号且提交内容
234	// 完全相同的重试只返回第一次成功的记录，不增加历史——即使后来再次改过
235	// 期限或档案已经销毁；沿用成功编号改变任何一项内容则返回编号冲突。
236	// 失败过的编号仍可用于重新提交。
237	func (s *Store) Revise(in ReviseInput) (RevisionRecord, error) {
238		revisionID, err := requireText(in.RevisionID, "修订编号")
239		if err != nil {
240			return RevisionRecord{}, err
241		}
242		archiveID, err := requireText(in.ArchiveID, "档案编号")
243		if err != nil {
244			return RevisionRecord{}, err
245		}
246		reason, err := requireText(in.Reason, "修订原因")
247		if err != nil {
248			return RevisionRecord{}, err
249		}
250		if err := requireDate(in.OriginalEnd, "原截止日"); err != nil {
251			return RevisionRecord{}, err
252		}
253		if err := requireDate(in.NewEnd, "新截止日"); err != nil {
254			return RevisionRecord{}, err
255		}
256		if err := requireDate(in.RevisedOn, "修订日期"); err != nil {
257			return RevisionRecord{}, err
258		}
259		if in.NewEnd.Equal(in.OriginalEnd) {
260			return RevisionRecord{}, fmt.Errorf("retention: 档案 %s 的新截止日 %s 与原截止日相同: %w",
261				archiveID, in.NewEnd, ErrRevisionEndUnchanged)
262		}
263	
264		var result RevisionRecord
265		err = s.mutate(func(data *storeData) error {
266			// 修订编号与销毁申请编号互不占用。
267			if _, ok := data.Manifests[revisionID]; ok {
268				return fmt.Errorf("retention: 修订编号 %s 已用作销毁申请编号: %w",
269					revisionID, ErrRevisionConflict)
270			}
271			// 同编号重试：内容完全相同则取回第一次成功的记录（即使期限后来
272			// 再次改动或档案已销毁）；改变任何一项内容即编号冲突。
273			if owner, rec := findRevision(data, revisionID); rec != nil {
274				if sameRevision(owner, rec, archiveID, in, reason) {
275					result = revisionFromRecord(archiveID, rec)
276					return nil
277				}
278				return fmt.Errorf("retention: 修订编号 %s 已成功使用，本次内容与原修订不一致: %w",
279					revisionID, ErrRevisionConflict)
280			}
281	
282			ar, ok := data.Archives[archiveID]
283			if !ok {
284				return fmt.Errorf("retention: 档案 %s 不存在，不能修订截止日: %w", archiveID, ErrNotFound)
285			}
286			if ar.Destroyed {
287				return fmt.Errorf("retention: 档案 %s 已销毁，不能修订截止日: %w", archiveID, ErrDestroyed)
288			}
289			if in.NewEnd.Before(ar.Start) {
290				return fmt.Errorf("retention: 档案 %s 的新截止日 %s 早于起算日 %s: %w",
291					archiveID, in.NewEnd, ar.Start, ErrRetentionEndBeforeStart)
292			}
293			// 排他锁内比较并更新：两个程序同时修订同一截止日，只有先成功者生效。
294			if !ar.End.Equal(in.OriginalEnd) {
295				return &RetentionEndChangedError{ArchiveID: archiveID, CurrentEnd: ar.End}
296			}
297			rec := &revisionRecord{
298				ID:        revisionID,
299				OldEnd:    ar.End,
300				NewEnd:    in.NewEnd,
301				RevisedOn: in.RevisedOn,
302				Reason:    reason,
303			}
304			ar.Revisions = append(ar.Revisions, rec)
305			ar.End = in.NewEnd
306			result = revisionFromRecord(archiveID, rec)
307			return nil
308		})
309		if err != nil {
310			return RevisionRecord{}, err
311		}
312		return result, nil
313	}
314	
315	// findRevision 在整个保管库内按修订编号查找已成功的修订，
316	// 返回所属档案与修订记录；不存在时返回 nil, nil。
317	func findRevision(data *storeData, revisionID string) (*archiveRecord, *revisionRecord) {
318		for _, ar := range data.Archives {
319			for _, rec := range ar.Revisions {
320				if rec.ID == revisionID {
321					return ar, rec
322				}
323			}
324		}
325		return nil, nil
326	}
327	
328	// sameRevision 判断本次提交与已成功的修订内容是否完全一致。
329	// 文本比较以去除首尾空白后的值为准（archiveID 与 reason 须已规范化）。
330	func sameRevision(owner *archiveRecord, rec *revisionRecord, archiveID string, in ReviseInput, reason string) bool {
331		return owner.ID == archiveID &&
332			rec.OldEnd.Equal(in.OriginalEnd) &&
333			rec.NewEnd.Equal(in.NewEnd) &&
334			rec.RevisedOn.Equal(in.RevisedOn) &&
335			rec.Reason == reason
336	}
337	
338	func revisionFromRecord(archiveID string, rec *revisionRecord) RevisionRecord {
339		return RevisionRecord{
340			RevisionID: rec.ID,
341			ArchiveID:  archiveID,
342			OldEnd:     rec.OldEnd,
343			NewEnd:     rec.NewEnd,
344			RevisedOn:  rec.RevisedOn,
345			Reason:     rec.Reason,
346		}
347	}
348	
349	// Destroy 办理一次销毁申请。
350	//
351	// 只有名单中全部档案都存在、按处理日期已到期（处理日期不早于截止日，
352	// 截止日当天即到期）、未销毁且没有未解除冻结时，才会同时完成销毁，
353	// 并生成一份内容此后不可更改的已关闭清册。
354	//
355	// 名单为空、名单内编号重复或任一档案不符合条件时，整次申请失败，
356	// 不会留下部分销毁或清册。
357	//
358	// 同一申请编号此前已经成功办理时：处理日期与档案集合完全相同（顺序无关）
359	// 则返回原清册；沿用编号但改变日期或档案集合则失败。失败过的申请
360	// 在条件改变后可以用同一编号再次提交。
361	func (s *Store) Destroy(req DestructionRequest) (Manifest, error) {
362		applicationID, ids, seen, err := validateBatchInputs(req.ApplicationID, req.ProcessedOn, req.ArchiveIDs)
363		if err != nil {
364			return Manifest{}, err
365		}
366	
367		var result Manifest
368		err = s.mutate(func(data *storeData) error {
369			// 已成功的申请编号：幂等返回原清册，或因内容不一致失败。
370			if existing, ok := data.Manifests[applicationID]; ok {
371				if !sameApplication(existing, req.ProcessedOn, seen) {
372					return fmt.Errorf("retention: 申请编号 %s 已成功使用，本次日期或档案集合与原申请不一致: %w",
373						applicationID, ErrApplicationMismatch)
374				}
375				result = manifestFromRecord(existing)
376				return nil
377			}
378			// 销毁申请编号与修订编号互不占用。
379			if _, rec := findRevision(data, applicationID); rec != nil {
380				return fmt.Errorf("retention: 申请编号 %s 已用作修订编号: %w",
381					applicationID, ErrRevisionConflict)
382			}
383	
384			// 逐份校验，任一不符合条件则整体放弃（此时尚未改动任何记录）。
385			// 判断规则与只读核对共用 evaluateArchive：按提交顺序检查，
386			// 在第一份不能办理的档案处失败，同一档案的多个问题按固定先后取其首条。
387			for _, id := range ids {
388				r := evaluateArchive(data, id, req.ProcessedOn)
389				if len(r.Obstructions) > 0 {
390					return firstObstructionError(r, req.ProcessedOn)
391				}
392			}
393	
394			// 全部满足：生成关闭清册，内容为各档案当时登记内容的快照。
395			processedOn := req.ProcessedOn
396			rec := &manifestRecord{
397				ApplicationID: applicationID,
398				ProcessedOn:   &processedOn,
399			}
400			ordered := append([]string(nil), ids...)
401			sort.Strings(ordered)
402			for _, id := range ordered {
403				ar := data.Archives[id]
404				rec.Entries = append(rec.Entries, manifestEntry{
405					ID:       ar.ID,
406					Category: ar.Category,
407					Start:    ar.Start,
408					End:      ar.End,
409				})
410				ar.Destroyed = true
411				ar.ManifestID = applicationID
412			}
413			data.Manifests[applicationID] = rec
414			result = manifestFromRecord(rec)
415			return nil
416		})
417		if err != nil {
418			return Manifest{}, err
419		}
420		return result, nil
421	}
422	
423	// sameApplication 判断已成功申请与本次提交的处理日期和档案集合是否完全一致（顺序无关）。
424	// 调用前记录已通过 load 的语义校验，处理日期必然存在且有效。
425	func sameApplication(existing *manifestRecord, processedOn Date, idSet map[string]struct{}) bool {
426		if existing.ProcessedOn == nil || !existing.ProcessedOn.Equal(processedOn) {
427			return false
428		}
429		if len(existing.Entries) != len(idSet) {
430			return false
431		}
432		for _, e := range existing.Entries {
433			if _, ok := idSet[e.ID]; !ok {
434				return false
435			}
436		}
437		return true
438	}
439	
440	func manifestFromRecord(rec *manifestRecord) Manifest {
441		m := Manifest{
442			ApplicationID: rec.ApplicationID,
443			Entries:       make([]ManifestEntry, 0, len(rec.Entries)),
444		}
445		// 通过校验的已关闭清册必然带有有效处理日期；防御性保留零值兜底。
446		if rec.ProcessedOn != nil {
447			m.ProcessedOn = *rec.ProcessedOn
448		}
449		for _, e := range rec.Entries {
450			m.Entries = append(m.Entries, ManifestEntry{
451				ID:       e.ID,
452				Category: e.Category,
453				Start:    e.Start,
454				End:      e.End,
455			})
456		}
457		return m
458	}
459	
460	func freezeFromRecord(fr *freezeRecord) FreezeRecord {
461		out := FreezeRecord{
462			ID:            fr.ID,
463			Reason:        fr.Reason,
464			Released:      fr.Released,
465			ReleaseReason: fr.ReleaseReason,
466		}
467		// 通过校验的冻结必然带有有效冻结日期；防御性保留零值兜底。
468		if fr.FrozenOn != nil {
469			out.FrozenOn = *fr.FrozenOn
470		}
471		if fr.ReleasedOn != nil {
472			out.ReleasedOn = *fr.ReleasedOn
473		}
474		return out
475	}
476	
477	// History 按档案编号核对完整历史。
478	//
479	// 结果包含登记内容、最初与当前保管截止日、按成功顺序排列的全部修订记录、
480	// 全部冻结及解除历史、当前未解除冻结、销毁状态以及对应的已关闭清册。档案未登记时 found 为 false（err 为 nil），
481	// 这是明确的不存在结果。
482	func (s *Store) History(archiveID string) (h ArchiveHistory, found bool, err error) {
483		id := normalizeText(archiveID)
484		if id == "" {
485			return ArchiveHistory{}, false, fmt.Errorf("retention: 档案编号不能为空白: %w", ErrBlankField)
486		}
487		err = s.view(func(data *storeData) error {
488			ar, ok := data.Archives[id]
489			if !ok {
490				return nil
491			}
492			found = true
493			h = ArchiveHistory{
494				ID:                    ar.ID,
495				Category:              ar.Category,
496				Start:                 ar.Start,
497				InitialEnd:            ar.InitialEnd,
498				RetentionEnd:          ar.End,
499				Destroyed:             ar.Destroyed,
500				ManifestApplicationID: ar.ManifestID,
501				Revisions:             make([]RevisionRecord, 0, len(ar.Revisions)),
502				Freezes:               make([]FreezeRecord, 0, len(ar.Freezes)),
503			}
504			for _, rec := range ar.Revisions {
505				h.Revisions = append(h.Revisions, revisionFromRecord(ar.ID, rec))
506			}
507			for _, fr := range ar.Freezes {
508				view := freezeFromRecord(fr)
509				h.Freezes = append(h.Freezes, view)
510				if !fr.Released {
511					h.ActiveFreezes = append(h.ActiveFreezes, view)
512				}
513			}
514			if ar.Destroyed && ar.ManifestID != "" {
515				if rec, ok := data.Manifests[ar.ManifestID]; ok {
516					m := manifestFromRecord(rec)
517					h.Manifest = &m
518				}
519			}
520			return nil
521		})
522		if err != nil {
523			return ArchiveHistory{}, false, err
524		}
525		return h, found, nil
526	}
527	
528	// Manifest 按申请编号查询一份已关闭清册。不存在时 found 为 false。
529	func (s *Store) GetManifest(applicationID string) (m Manifest, found bool, err error) {
530		id := normalizeText(applicationID)
531		if id == "" {
532			return Manifest{}, false, fmt.Errorf("retention: 申请编号不能为空白: %w", ErrBlankField)
533		}
534		err = s.view(func(data *storeData) error {
535			if rec, ok := data.Manifests[id]; ok {
536				m = manifestFromRecord(rec)
537				found = true
538			}
539			return nil
540		})
541		if err != nil {
542			return Manifest{}, false, err
543		}
544		return m, found, nil
545	}
546

