// validateManifestIdentity 检查保存的清册集合中，用于查找每份清册的申请编号
// （清册集合对象的键）与该份清册内容里的 application_id 是否同为非空白文本
// 且逐字相同。
//
// 正常办理销毁保存的记录必然满足这一条：申请编号在办理时已经过去除首尾空白
// 的非空白校验，保存时同一编号同时用作集合键与清册内容的 application_id。
// 读取保存记录时却不能默认它成立：一份清册可以被挂在申请编号 APP-1 名下，
// 内容里的 application_id 却写成 APP-2，或该字段缺失、为 null、为空串、只有
// 空白。这样的清册无法说明自己属于哪次申请——按 APP-1 取回的清册、重放原
// 申请或查询 APP-1 历史拿到的清册都标着 APP-2，档案的清册归属却仍指向
// APP-1，整库都无法再使用。因此这类矛盾必须在进入任何业务操作前被拒绝，
// 绝不交付一个还能继续办理的保管库。
//
// 比较以 JSON 解码后的实际文本为准：直接写出的 "APP-1" 与通过 Unicode 转义
// 写出、解码后同为 APP-1 的编号仍属一致；但两处仅大小写不同（APP-1 与
// app-1）或首尾空白不同（"APP-1" 与 " APP-1 "）都不能当作一致——读取保存
// 记录时绝不做去首尾空白或大小写归一化。也绝不通过用查找编号补写清册、以
// 清册内容改号或删掉冲突记录来“修复”保存内容：正常办理时对申请编号去首尾
// 空白的行为继续保留，那只发生在办理入口，不会用来改动磁盘上的既有文本。
//
// 命中时返回可由 ErrCorruptState 识别的错误：
//   - 两处编号不同：说明是清册申请编号不一致，并同时给出查找编号与清册内容
//     里的申请编号；
//   - 清册内容缺少有效 application_id（字段缺失、为 null、空串或只有空白）：
//     指出对应的清册记录（按查找编号）与缺失位置（清册内容的 application_id）；
//   - 用于查找的键本身为空白：说明缺的是查找编号，并指出对应的清册记录，
//     同样按损坏拒绝。
//
// 校验覆盖整个保管库的全部清册：即使档案已经销毁、清册归属正确、条目快照、
// 处理日期与期限修订都完整合法，合法的归属与期限也不能掩盖申请编号矛盾。
// 任一清册身份不明，整份保管库都判为损坏——load 在每次查询、核对与办理前
// 都会重新执行校验，因此保管库打开后保存内容才出现这种问题时，下一次使用
// 有效输入（即使查询、核对或办理的是另一份正常档案或正常清册）也按整库
// 记录损坏失败，不返回正常历史、清册或部分报告，不写入任何业务变更，原
// 保存内容保持原样。
func validateManifestIdentity(data *storeData) error {
	// map 遍历顺序不稳定，按查找编号排序后再检查，保证错误信息稳定。
	lookupIDs := make([]string, 0, len(data.Manifests))
	for id := range data.Manifests {
		lookupIDs = append(lookupIDs, id)
	}
	sort.Strings(lookupIDs)
	for _, lookupID := range lookupIDs {
		// 用于查找清册的编号本身也必须是非空白文本：空白键无法给清册一个
		// 有效的申请身份。打印带引号的键，空串与纯空白键都能在信息中看清。
		if strings.TrimSpace(lookupID) == "" {
			return fmt.Errorf(
				"retention: 保存的清册集合中用于查找清册的申请编号为空白（键 %q），该清册记录没有有效的查找编号，记录已损坏: %w",
				lookupID, ErrCorruptState)
		}
		mr := data.Manifests[lookupID]
		if mr == nil || strings.TrimSpace(mr.ApplicationID) == "" {
			return fmt.Errorf(
				"retention: 按查找编号 %q 找到的清册记录内容里缺少有效的申请编号（application_id 缺失、为 null、为空串或只有空白），无法确认该清册属于哪次申请，记录已损坏: %w",
				lookupID, ErrCorruptState)
		}
		// 逐字比较解码后的文本，不做去空白或大小写归一化：
		// 首尾空白或大小写不同也算两处编号不一致。
		if mr.ApplicationID != lookupID {
			return fmt.Errorf(
				"retention: 按查找编号 %q 找到的清册记录，其内容里的申请编号 application_id 为 %q，两处编号不一致，记录已损坏: %w",
				lookupID, mr.ApplicationID, ErrCorruptState)
		}
	}
	return nil
}

